//! Typed SQLite physical cells. The platform supplies type-preserving values;
//! Rust retains the V5 fingerprint and model validation. No JSON number coercion.
use crate::{local_transaction::Error,sync_codec as c};
#[derive(Clone,Debug,PartialEq)]pub enum Cell{Null,Integer(i64),Real(f64),Text(String)}
pub fn physical_row(cells:&[Cell])->Result<String,Error>{let mut values=Vec::with_capacity(cells.len());for cell in cells{values.push(match cell{Cell::Null=>"N".into(),Cell::Integer(v)=>format!("I{v}"),Cell::Real(v)=>{if !v.is_finite(){return Err(Error::CorruptFloat)}format!("R{:016x}",v.to_bits())},Cell::Text(v)=>format!("T{v}")});}Ok(c::sha256_hex(&serde_json::to_string(&values).map_err(|_|Error::Storage)?))}
pub fn physical(cells:&[Cell],bits:Option<(String,i64,i64)>)->Result<String,Error>{let base=physical_row(cells)?;Ok(c::sha256_hex(&serde_json::json!([base,bits]).to_string()))}
fn text(cells:&[Cell],at:usize)->Result<String,Error>{match cells.get(at){Some(Cell::Text(v))if v.encode_utf16().count()<=4096=>Ok(v.clone()),_=>Err(Error::Storage)}}
fn int(cells:&[Cell],at:usize)->Result<i32,Error>{match cells.get(at){Some(Cell::Integer(v))=>i32::try_from(*v).map_err(|_|Error::Storage),_=>Err(Error::Storage)}}
fn real(cells:&[Cell],at:usize)->Result<f32,Error>{match cells.get(at){Some(Cell::Real(v))if v.is_finite()&&(*v as f32).is_finite()=>Ok(*v as f32),Some(Cell::Integer(v))if (*v as f32).is_finite()=>Ok(*v as f32),_=>Err(Error::CorruptFloat)}}
pub fn log(cells:&[Cell],bits:Option<(String,i64,i64)>)->Result<Option<crate::track_log::CycleDayLog>,Error>{if cells.is_empty(){return if bits.is_none(){Ok(None)}else{Err(Error::CorruptFloat)}}if cells.len()!=15{return Err(Error::Storage)}let mut log=crate::track_log::CycleDayLog{date_string:text(cells,0)?,flow_level:text(cells,1)?,energy_level:text(cells,2)?,mood_level:text(cells,3)?,symptoms_csv:text(cells,4)?,vaginal_health_csv:text(cells,5)?,urinary_health_csv:text(cells,6)?,cervical_mucus:text(cells,7)?,ovulation_test:text(cells,8)?,bbt_celsius:real(cells,9)?,sleep_hours:real(cells,10)?,sleep_quality:text(cells,11)?,water_glasses:int(cells,12)?,notes:text(cells,13)?,pain_intensity:int(cells,14)?};
 if let Some((hash,b,s))=bits{if hash!=physical_row(cells)?||!(0..=u32::MAX as i64).contains(&b)||!(0..=u32::MAX as i64).contains(&s){return Err(Error::CorruptFloat)}let bb=f32::from_bits(b as u32);let ss=f32::from_bits(s as u32);if !bb.is_finite()||!ss.is_finite()||bb!=log.bbt_celsius||ss!=log.sleep_hours{return Err(Error::CorruptFloat)}log.bbt_celsius=bb;log.sleep_hours=ss;}
 Ok(Some(log))}
fn boolean(cells:&[Cell],at:usize)->Result<bool,Error>{match int(cells,at)?{0=>Ok(false),1=>Ok(true),_=>Err(Error::Storage)}}
pub fn settings(cells:&[Cell])->Result<Option<c::CycleSettings>,Error>{if cells.is_empty(){return Ok(None)}if cells.len()!=15||int(cells,0)?!=1{return Err(Error::Storage)}Ok(Some(c::CycleSettings{id:1,is_onboarding_completed:boolean(cells,1)?,selected_goals_csv:text(cells,2)?,last_period_start_date:text(cells,3)?,average_cycle_length:int(cells,4)?,period_duration:int(cells,5)?,luteal_phase_days:int(cells,6)?,is_app_lock_enabled:boolean(cells,7)?,lock_timeout_minutes:int(cells,8)?,is_discreet_notification_mode:boolean(cells,9)?,is_pregnancy_mode:boolean(cells,10)?,pregnancy_due_date:text(cells,11)?,remind_period:boolean(cells,12)?,remind_fertile:boolean(cells,13)?,remind_daily_log:boolean(cells,14)?}))}
pub fn profile(cells:&[Cell])->Result<Option<c::OnboardingProfile>,Error>{if cells.is_empty(){return Ok(None)}if cells.len()!=18||int(cells,0)?!=1{return Err(Error::Storage)}let timestamp=match cells.get(2){Some(Cell::Integer(v))=>*v,_=>return Err(Error::Storage)};Ok(Some(c::OnboardingProfile{id:1,is_completed:boolean(cells,1)?,completed_at_timestamp:timestamp,is_age_verified:boolean(cells,3)?,is_terms_agreed:boolean(cells,4)?,account_mode:text(cells,5)?,selected_goals_csv:text(cells,6)?,last_period_date_string:text(cells,7)?,last_period_end_date_string:text(cells,8)?,approximate_period_choice:text(cells,9)?,cycle_length_option:text(cells,10)?,cycle_length_days:int(cells,11)?,period_duration_days:int(cells,12)?,remind_fertile_window:boolean(cells,13)?,typical_symptoms_csv:text(cells,14)?,typical_energy:text(cells,15)?,typical_sleep_quality:text(cells,16)?,has_completed_deep_baseline:boolean(cells,17)?}))}
#[cfg(test)]mod tests{use super::*;#[test]fn physical_types_raw_double_bits_and_absence_remain_distinct(){assert_ne!(physical_row(&[Cell::Integer(1)]).unwrap(),physical_row(&[Cell::Real(1.0)]).unwrap());assert_ne!(physical_row(&[Cell::Real(-0.0)]).unwrap(),physical_row(&[Cell::Real(0.0)]).unwrap());assert_ne!(physical_row(&[]).unwrap(),physical_row(&[Cell::Null]).unwrap());assert!(physical_row(&[Cell::Real(f64::NAN)]).is_err());}#[test]fn log_cell_sidecar_preserves_signedzero_and_rejects_wrong_type(){let mut cells=vec![Cell::Text("".into());15];cells[0]=Cell::Text("2024-04-03".into());cells[9]=Cell::Real(0.0);cells[10]=Cell::Real(0.0);cells[12]=Cell::Integer(0);cells[14]=Cell::Integer(0);let hash=physical_row(&cells).unwrap();let l=log(&cells,Some((hash,0x80000000,0x80000000))).unwrap().unwrap();assert_eq!(l.bbt_celsius.to_bits(),0x80000000);cells[12]=Cell::Real(1.0);assert!(log(&cells,None).is_err());}}

#[cfg(test)]mod decoder_rejection_tests{use super::*;
 fn row()->Vec<Cell>{let mut r=vec![Cell::Text("".into());15];r[0]=Cell::Text("2024-04-03".into());r[9]=Cell::Real(36.5);r[10]=Cell::Real(7.0);r[12]=Cell::Integer(2);r[14]=Cell::Integer(0);r}
 #[test]fn storage_types_width_finiteness_and_float_sidecar_are_not_coerced(){for bad in [Cell::Text("2".into()),Cell::Real(2.0),Cell::Integer(i64::MAX),Cell::Null]{let mut r=row();r[12]=bad;assert!(log(&r,None).is_err());}for bad in [f64::NAN,f64::INFINITY,f64::MAX]{let mut r=row();r[9]=Cell::Real(bad);assert!(log(&r,None).is_err());}let r=row();let hash=physical_row(&r).unwrap();for bits in [("different-hash".into(),36.5f32.to_bits()as i64,7f32.to_bits()as i64),(hash.clone(),36.6f32.to_bits()as i64,7f32.to_bits()as i64),(hash.clone(),i64::MAX,0),(hash,f32::NAN.to_bits()as i64,0)]{assert!(log(&r,Some(bits)).is_err());}assert!(log(&[],Some(("orphan".into(),0,0))).is_err());}
}

/// Full source-domain row for a platform write. Not a partial sync payload.
pub fn log_row(value:&crate::track_log::CycleDayLog)->Result<Vec<Cell>,Error>{let l=value;let row=vec![Cell::Text(l.date_string.clone()),Cell::Text(l.flow_level.clone()),Cell::Text(l.energy_level.clone()),Cell::Text(l.mood_level.clone()),Cell::Text(l.symptoms_csv.clone()),Cell::Text(l.vaginal_health_csv.clone()),Cell::Text(l.urinary_health_csv.clone()),Cell::Text(l.cervical_mucus.clone()),Cell::Text(l.ovulation_test.clone()),Cell::Real(l.bbt_celsius as f64),Cell::Real(l.sleep_hours as f64),Cell::Text(l.sleep_quality.clone()),Cell::Integer(l.water_glasses as i64),Cell::Text(l.notes.clone()),Cell::Integer(l.pain_intensity as i64)];log(&row,None)?;Ok(row)}
pub fn settings_row(s:&c::CycleSettings)->Result<Vec<Cell>,Error>{let row=vec![Cell::Integer(s.id as i64),Cell::Integer(s.is_onboarding_completed as i64),Cell::Text(s.selected_goals_csv.clone()),Cell::Text(s.last_period_start_date.clone()),Cell::Integer(s.average_cycle_length as i64),Cell::Integer(s.period_duration as i64),Cell::Integer(s.luteal_phase_days as i64),Cell::Integer(s.is_app_lock_enabled as i64),Cell::Integer(s.lock_timeout_minutes as i64),Cell::Integer(s.is_discreet_notification_mode as i64),Cell::Integer(s.is_pregnancy_mode as i64),Cell::Text(s.pregnancy_due_date.clone()),Cell::Integer(s.remind_period as i64),Cell::Integer(s.remind_fertile as i64),Cell::Integer(s.remind_daily_log as i64)];settings(&row)?;Ok(row)}

pub fn profile_row(p:&c::OnboardingProfile)->Result<Vec<Cell>,Error>{let row=vec![Cell::Integer(p.id as i64),Cell::Integer(p.is_completed as i64),Cell::Integer(p.completed_at_timestamp),Cell::Integer(p.is_age_verified as i64),Cell::Integer(p.is_terms_agreed as i64),Cell::Text(p.account_mode.clone()),Cell::Text(p.selected_goals_csv.clone()),Cell::Text(p.last_period_date_string.clone()),Cell::Text(p.last_period_end_date_string.clone()),Cell::Text(p.approximate_period_choice.clone()),Cell::Text(p.cycle_length_option.clone()),Cell::Integer(p.cycle_length_days as i64),Cell::Integer(p.period_duration_days as i64),Cell::Integer(p.remind_fertile_window as i64),Cell::Text(p.typical_symptoms_csv.clone()),Cell::Text(p.typical_energy.clone()),Cell::Text(p.typical_sleep_quality.clone()),Cell::Integer(p.has_completed_deep_baseline as i64)];profile(&row)?;Ok(row)}
